tokens.css:
--color-bg: #fbf6f1;
--color-surface: #fffaf6;
--color-text: #3b2a22;
--color-text-muted: #7a6358;
--color-border: #e8dcd3;
--color-primary: #ea8ab9;
--color-on-primary: #3b2a22;
--color-accent: #e8c6d7;
--color-on-accent: #3b2a22;
--font-display: "Manrope", system-ui, sans-serif;
--font-body: "Work Sans", system-ui, sans-serif;
--text-sm: 14px;
--text-base: 18px;
--text-lg: 23px;
--text-xl: 28px;
--text-2xl: 35px;
--text-3xl: 44px;
--radius-control: 8px;
--radius-card: 12px;
--space-section: 128px;
--shadow-card: 0 1px 2px color-mix(in oklab, var(--color-text) 8%, transparent), 0 10px 30px color-mix(in oklab, var(--color-text) 12%, transparent);
